You are implementing Task 2.2: UI Component Library

## Task Description

Create the reusable UI component library for Vibe Voyager — a space-themed game with clean minimalist sci-fi aesthetics. All components use the design system already configured in Tailwind v4 (globals.css has the theme tokens).

IMPORTANT: Import animations from `motion/react`, NOT from `framer-motion`. The package is called `motion`.
IMPORTANT: Use `clsx` for className composition.

### Files to Create

**1. `components/ui/GlassPanel.tsx`**
```tsx
'use client'

import { clsx } from 'clsx'
import { motion } from 'motion/react'

interface GlassPanelProps {
  children: React.ReactNode
  className?: string
  hover?: boolean
  glow?: 'nebula' | 'signal' | 'terracotta' | 'starlight'
  padding?: 'none' | 'sm' | 'md' | 'lg'
  as?: 'div' | 'section' | 'article'
}

const glowStyles = {
  nebula: 'shadow-glow-nebula',
  signal: 'shadow-glow-signal',
  terracotta: 'shadow-glow-terracotta',
  starlight: 'shadow-glow-starlight',
}

const paddingStyles = {
  none: '',
  sm: 'p-3',
  md: 'p-5',
  lg: 'p-8',
}

export function GlassPanel({ children, className, hover = false, glow, padding = 'md', as = 'div' }: GlassPanelProps) {
  const Component = motion.create(as)

  return (
    <Component
      className={clsx(
        'bg-glass backdrop-blur-md border border-glass-border rounded-xl',
        paddingStyles[padding],
        glow && glowStyles[glow],
        hover && 'transition-colors hover:bg-glass-hover hover:border-glass-active cursor-pointer',
        className
      )}
      whileHover={hover ? { scale: 1.02 } : undefined}
      transition={{ type: 'spring', stiffness: 400, damping: 25 }}
    >
      {children}
    </Component>
  )
}
```

**2. `components/ui/StarfieldBackground.tsx`**
```tsx
'use client'

import { useEffect, useRef } from 'react'

interface Star {
  x: number
  y: number
  size: number
  opacity: number
  speed: number
}

interface StarfieldBackgroundProps {
  density?: number
  speed?: number
  className?: string
}

export function StarfieldBackground({ density = 200, speed = 0.5, className }: StarfieldBackgroundProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const starsRef = useRef<Star[]>([])
  const animRef = useRef<number>(0)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const resize = () => {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
      initStars()
    }

    const initStars = () => {
      starsRef.current = []
      for (let i = 0; i < density; i++) {
        // 3 layers: distant (slow, small, dim), medium, close (fast, big, bright)
        const layer = Math.random()
        let starSpeed: number, size: number, opacity: number
        if (layer < 0.6) {
          // Distant
          starSpeed = 0.1 * speed
          size = Math.random() * 1 + 0.5
          opacity = Math.random() * 0.3 + 0.1
        } else if (layer < 0.85) {
          // Medium
          starSpeed = 0.3 * speed
          size = Math.random() * 1.5 + 1
          opacity = Math.random() * 0.4 + 0.3
        } else {
          // Close
          starSpeed = 0.6 * speed
          size = Math.random() * 2 + 1.5
          opacity = Math.random() * 0.4 + 0.5
        }
        starsRef.current.push({
          x: Math.random() * canvas.width,
          y: Math.random() * canvas.height,
          size,
          opacity,
          speed: starSpeed,
        })
      }
    }

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height)

      for (const star of starsRef.current) {
        star.y += star.speed
        if (star.y > canvas.height) {
          star.y = 0
          star.x = Math.random() * canvas.width
        }

        ctx.beginPath()
        ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2)
        ctx.fillStyle = `rgba(232, 224, 212, ${star.opacity})`
        ctx.fill()
      }

      animRef.current = requestAnimationFrame(animate)
    }

    resize()
    animate()
    window.addEventListener('resize', resize)

    return () => {
      cancelAnimationFrame(animRef.current)
      window.removeEventListener('resize', resize)
    }
  }, [density, speed])

  return (
    <canvas
      ref={canvasRef}
      className={clsx('fixed inset-0 -z-10', className)}
      style={{ background: '#0a0f1a' }}
    />
  )
}
```
Note: Add `import { clsx } from 'clsx'` at top.

**3. `components/ui/TypewriterText.tsx`**
```tsx
'use client'

import { useState, useEffect, useCallback } from 'react'
import { clsx } from 'clsx'

interface TypewriterTextProps {
  text: string
  speed?: number
  className?: string
  onComplete?: () => void
  showCursor?: boolean
}

export function TypewriterText({ text, speed = 30, className, onComplete, showCursor = true }: TypewriterTextProps) {
  const [displayedText, setDisplayedText] = useState('')
  const [isComplete, setIsComplete] = useState(false)

  const skipToEnd = useCallback(() => {
    setDisplayedText(text)
    setIsComplete(true)
    onComplete?.()
  }, [text, onComplete])

  useEffect(() => {
    setDisplayedText('')
    setIsComplete(false)
    let index = 0

    const interval = setInterval(() => {
      if (index < text.length) {
        setDisplayedText(text.slice(0, index + 1))
        index++
      } else {
        clearInterval(interval)
        setIsComplete(true)
        onComplete?.()
      }
    }, speed)

    return () => clearInterval(interval)
  }, [text, speed, onComplete])

  return (
    <span className={clsx(className)} onClick={!isComplete ? skipToEnd : undefined}>
      {displayedText}
      {showCursor && !isComplete && (
        <span className="inline-block w-2 h-5 ml-0.5 bg-starlight animate-pulse" />
      )}
    </span>
  )
}
```

